-- Build NDIS Administration Fundamentals against current 2026 context.
insert into public.training_courses (slug,title,summary,category,country_focus,estimated_minutes,recommended_order,status,content_version,trademark_disclaimer,reviewed_by,last_reviewed_at,published_at,created_at,updated_at)
values ('ndis-administration-fundamentals','NDIS Administration Fundamentals','Administrative training for Filipino VAs supporting Australian NDIS providers, covering participant records, service agreements, support evidence, claims, payment pathways, pricing exceptions, complaints, safeguarding, and 2026 registration awareness.','industry','Australia',300,24,'draft',1,'NDIS and related names belong to the Australian Government and relevant agencies. This independent administrative course is not affiliated with, certified by, or endorsed by the NDIA or NDIS Quality and Safeguards Commission. It does not provide legal, compliance, clinical, support-planning, or funding advice.',null,null,null,now(),now())
