insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='ndis-administration-fundamentals'),'NDIS Context and 2026 Changes','Understand the ecosystem and changed registration environment.',1) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=1),'ndis-ecosystem-participants-providers-and-va-boundaries','NDIS Ecosystem, Participants, Providers, and VA Boundaries','NDIS administration involves participants, providers, plan managers, support coordinators, nominees, NDIA systems, the NDIS Commission, and other parties. A VA needs to understand the relationships before touching participant records or provider workflows.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize key NDIS actors","Understand common provider admin workflows","Separate administrative support from support planning, clinical, legal, or compliance decisions"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"NDIS administration involves participants, providers, plan managers, support coordinators, nominees, NDIA systems, the NDIS Commission, and other parties. A VA needs to understand the relationships before touching participant records or provider workflows."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Participants choose and receive supports according to their plans and arrangements.","Providers deliver supports and have record, conduct, billing, and other obligations.","Plan management type affects how providers are paid.","The NDIS Commission regulates quality and safeguards and provider registration matters.","A VA can support records, scheduling, invoicing, document tracking, and communication under the provider''s approved process."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Map the provider''s registration/service scope.","Identify participant, plan-manager, support-coordinator, practitioner, and internal contacts.","Identify the systems and portals used.","List the VA''s approved participant-admin tasks.","Document escalation for safeguarding, incidents, complaints, restrictive practices, clinical questions, pricing, claims, or registration issues."]},{"type":"callout","title":"Administrative boundary","text":"Do not advise participants about what supports they should buy, interpret their plan, make safeguarding decisions, determine provider compliance, or represent yourself as the NDIS, NDIA, NDIS Commission, plan manager, support coordinator, or qualified practitioner."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Calling every participant issue an NDIS issue instead of finding the correct owner","Giving plan advice because you can see the plan","Using provider access outside assigned tasks","Confusing NDIA and NDIS Commission roles","Telling a participant a support will definitely be funded"]},{"type":"scenario","title":"Practice scenario","text":"A participant asks whether the NDIS will pay for a new service your provider offers. Explain the administrative response and who should handle the eligibility or funding question."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Know the actors.","Use provider-approved workflows.","Keep advice and compliance decisions with authorized people.","Document every handoff."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=1),'2026-provider-registration-changes-and-sil-administration-awareness','2026 Provider Registration Changes and SIL Administration Awareness','From 1 July 2026, supported independent living providers are subject to new mandatory registration and SIL Practice Standards. VAs supporting providers need awareness of the changed environment without pretending to interpret registration law.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize the 2026 SIL registration change","Understand why registration status affects admin workflows","Know when to route questions to compliance leadership"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"From 1 July 2026, supported independent living providers are subject to new mandatory registration and SIL Practice Standards. VAs supporting providers need awareness of the changed environment without pretending to interpret registration law."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["The NDIS Commission states that SIL providers face mandatory registration requirements from 1 July 2026, with transition pathways depending on provider status.","New SIL Practice Standards apply to registered SIL providers.","Registration, audit, key personnel, worker screening, and scope can affect provider operations.","The VA may track evidence, dates, documents, and tasks but does not decide whether the provider is compliant.","NDIS digital platform services also entered mandatory registration requirements from 1 July 2026."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Record the provider''s confirmed registration status and responsible compliance owner.","Maintain the approved compliance calendar.","Track requested evidence, certificates, audit items, and due dates.","Use official Commission sources for current instructions.","Escalate any uncertainty about registration group, transition pathway, audit scope, or practice-standard interpretation.","Do not change public claims about registration without approval."]},{"type":"callout","title":"Administrative boundary","text":"This course does not determine whether a provider must register, which registration group applies, whether transition arrangements are satisfied, or whether the provider meets Practice Standards. Those decisions require current official guidance and responsible compliance advice."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using pre-2026 SIL guidance","Assuming a submitted application equals approved registration","Calling the VA ''NDIS certified''","Editing registration claims on the website from memory","Treating an audit checklist as legal advice"]},{"type":"scenario","title":"Practice scenario","text":"A provider says they applied for SIL registration and asks you to update the website to ''fully registered'' before the decision arrives. Explain the safe admin response."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use current 2026 sources.","Track status precisely.","Do not overstate registration.","Keep compliance interpretation with the provider''s responsible owner."]}]'::jsonb,30,2,false,1,null,null,now(),now())
