insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='ndis-administration-fundamentals'),'Participant and Agreement Administration','Protect participant data and coordinate agreements.',2) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=2),'participant-intake-consent-privacy-and-record-setup','Participant Intake, Consent, Privacy, and Record Setup','Participant records can contain identity, disability, support, contact, funding, incident, health, and financial information. Administrative accuracy and privacy are fundamental.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Set up participant admin records safely","Track consent and authorized contacts","Minimize sensitive-data handling"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Participant records can contain identity, disability, support, contact, funding, incident, health, and financial information. Administrative accuracy and privacy are fundamental."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Participant information can be highly sensitive.","Providers should maintain complete and accurate records of supports delivered.","Consent and authority to communicate with nominees, plan managers, coordinators, or others should follow provider process.","Different systems may hold service, roster, invoice, case-note, and agreement information.","Offshore access should use approved controls and minimum necessary permissions."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Verify participant identity using provider process.","Capture only approved intake fields.","Record authorized contacts and communication preferences.","Attach service agreements/referrals/supporting documents to the correct record.","Limit access to what your tasks require.","Create missing-information tasks.","Escalate privacy or consent uncertainty."]},{"type":"callout","title":"Administrative boundary","text":"Do not infer participant capacity, consent, guardianship, nominee authority, diagnosis, risk, or support needs from documents. Use the provider''s approved evidence and escalation process."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Emailing participant documents to a personal account","Adding a family member as authorized contact from assumption","Copying sensitive data into AI tools","Creating duplicate participant records","Leaving consent status undocumented"]},{"type":"scenario","title":"Practice scenario","text":"A family member emails asking for a participant''s service schedule, but the record does not clearly show their authority. Explain the safe response."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Verify identity and authority.","Use minimum necessary access.","Keep sensitive records in approved systems.","Escalate consent uncertainty."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=2),'service-agreements-and-administrative-change-tracking','Service Agreements and Administrative Change Tracking','Current NDIS guidance describes service agreements as documenting agreed supports, costs, payment arrangements, responsibilities, changes, and complaint pathways. A VA can coordinate documents while keeping negotiation and interpretation with authorized people.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand service-agreement administration","Track versions and signatures","Separate document coordination from agreement advice"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Current NDIS guidance describes service agreements as documenting agreed supports, costs, payment arrangements, responsibilities, changes, and complaint pathways. A VA can coordinate documents while keeping negotiation and interpretation with authorized people."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Service agreements describe agreed supports and how they will be delivered.","They can cover pricing, travel, payment method, cancellations, responsibilities, changes, and dispute processes.","Written service agreements are recommended broadly and mandatory in some support contexts such as SDA.","Participants should understand agreements and changes.","The provider''s approved template and responsible staff should control substantive terms."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Use the current approved template.","Populate only approved participant/provider facts.","Track draft, sent, questions, agreed changes, signed/executed, review, and expiry status.","Preserve version history.","Route requested term changes to authorized staff.","Store the final agreement in the source system.","Create review/reminder tasks."]},{"type":"callout","title":"Administrative boundary","text":"Do not interpret contract terms, negotiate support prices or cancellation conditions, pressure a participant to sign, or decide whether an agreement legally satisfies NDIS requirements."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Editing substantive terms from a participant email without approval","Losing the signed version","Treating silence as acceptance","Using an expired price or template","Explaining legal meaning yourself"]},{"type":"scenario","title":"Practice scenario","text":"A participant asks you to remove a cancellation clause before signing. Describe the admin handoff and version-control steps."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Coordinate, don''t negotiate.","Preserve versions.","Track review dates.","Keep substantive decisions with authorized staff."]}]'::jsonb,30,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='ndis-administration-fundamentals'),'Service Evidence and Payments','Connect delivered supports to accurate billing records.',3) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=3),'rosters-support-logs-case-notes-and-evidence-administration','Rosters, Support Logs, Case Notes, and Evidence Administration','NDIS guidance emphasizes complete and accurate records of supports delivered, including records such as invoices, support logs, rosters, case notes, and service agreements. Administrative systems need to connect scheduled support with delivered support and billing evidence.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Maintain support-delivery records","Reconcile roster and evidence exceptions","Protect practitioner and worker-authored records"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"NDIS guidance emphasizes complete and accurate records of supports delivered, including records such as invoices, support logs, rosters, case notes, and service agreements. Administrative systems need to connect scheduled support with delivered support and billing evidence."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Rostered time is not automatically proof of delivered support.","Worker logs or case notes may contain sensitive information.","Changes, cancellations, no-shows, travel, and support variations need approved recording.","Claims should be supported by accurate service evidence.","The VA can identify missing documentation without rewriting worker evidence."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Compare scheduled support with completed/delivered status.","Check required worker evidence exists.","Flag missing, contradictory, or late records.","Track cancellations or changes according to provider policy.","Link support records to invoice/claim preparation.","Escalate concerning, incident-related, or clinical content.","Do not alter worker-authored evidence to make records fit."]},{"type":"callout","title":"Administrative boundary","text":"Do not manufacture case notes, alter support times, backfill evidence from guesswork, or decide whether a record proves compliance."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Billing from roster alone","Editing worker notes for consistency","Ignoring time discrepancies","Copying sensitive case notes into general chat","Closing missing evidence because the worker is unavailable"]},{"type":"scenario","title":"Practice scenario","text":"A roster shows a three-hour support, but the worker''s log shows two hours and a cancellation note for the final hour. Explain the reconciliation and escalation."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Scheduled is not delivered.","Preserve worker evidence.","Resolve discrepancies before claims.","Keep sensitive notes controlled."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=3),'ndis-invoices-plan-management-types-and-payment-requests','NDIS Invoices, Plan Management Types, and Payment Requests','How a provider gets paid depends on participant funding management and current NDIS payment processes. Current NDIS guidance distinguishes self-managed, plan-managed, and NDIA-managed arrangements and identifies information needed for payment requests.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize major payment pathways","Prepare claim or invoice data carefully","Separate claim preparation from compliance judgment"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"How a provider gets paid depends on participant funding management and current NDIS payment processes. Current NDIS guidance distinguishes self-managed, plan-managed, and NDIA-managed arrangements and identifies information needed for payment requests."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Self-managed participants may receive and pay provider invoices.","Plan-managed arrangements involve the plan manager payment workflow.","NDIA-managed providers may use provider portals for claims/payment requests.","Payment requests require accurate participant, support date, support item, and price information.","Provider portal and system requirements can change."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm the participant''s approved funding-management pathway.","Confirm the support delivered and evidence.","Use the provider''s approved support item and price source.","Prepare invoice or payment-request fields.","Check dates, participant identifiers, quantities, and amounts.","Route pricing, support-item, cancellation, or claim-rule uncertainty.","Track submitted, paid, rejected, or queried status."]},{"type":"callout","title":"Administrative boundary","text":"Do not select support items, determine claim eligibility, alter delivery evidence, exceed pricing limits, or submit questionable claims merely to obtain payment."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using the wrong management pathway","Claiming from roster instead of delivered evidence","Changing support item to make a claim pass","Reusing outdated prices","Ignoring rejected-claim reasons"]},{"type":"scenario","title":"Practice scenario","text":"A claim is rejected and a colleague suggests choosing a different support item with a similar name. Explain the correct admin response."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Claim from delivered evidence.","Use approved current support items and prices.","Track management type.","Escalate claim judgment."]}]'::jsonb,30,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='ndis-administration-fundamentals'),'Billing Exceptions and Safeguarding','Handle high-risk administrative issues correctly.',4) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=4),'pricing-cancellations-travel-and-billing-exceptions','Pricing, Cancellations, Travel, and Billing Exceptions','NDIS pricing arrangements and provider agreements can affect support prices, travel, cancellations, and other billable items. These are high-risk areas for a VA to guess.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize common billing-exception categories","Track pricing source and agreement terms","Escalate uncertain charges"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"NDIS pricing arrangements and provider agreements can affect support prices, travel, cancellations, and other billable items. These are high-risk areas for a VA to guess."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["NDIS pricing arrangements and limits can change.","Provider charges must align with applicable rules and participant agreements.","Travel, cancellation, non-face-to-face, or other items may have conditions.","Different supports or management types may have different workflows.","The VA should document the source used for billing decisions."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify the support and date.","Check the current provider-approved pricing reference.","Check the participant''s agreement and approved billing rule.","Confirm delivered/cancelled/travel evidence.","Prepare the billing record.","Flag any mismatch or ambiguity.","Route to billing/compliance owner before submission."]},{"type":"callout","title":"Administrative boundary","text":"Do not interpret pricing rules, determine whether a cancellation or travel charge is permitted, or override system validation from your own judgment."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using last year''s price list","Charging from memory","Assuming all cancellations are billable","Adding travel without evidence","Ignoring agreement terms"]},{"type":"scenario","title":"Practice scenario","text":"A cancellation occurred late, but the participant''s service agreement and the provider''s current billing rule appear inconsistent. Describe the exception handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use current sources.","Check agreement and evidence.","Do not guess billability.","Record the reviewer decision."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=4),'complaints-incidents-safeguarding-and-escalation','Complaints, Incidents, Safeguarding, and Escalation','Participant safety and rights are more important than administrative convenience. A VA may receive complaints, incident information, abuse or neglect concerns, privacy issues, or urgent messages that require immediate provider escalation.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize high-risk messages","Preserve participant wording and evidence","Use the provider''s incident and complaint escalation process"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Participant safety and rights are more important than administrative convenience. A VA may receive complaints, incident information, abuse or neglect concerns, privacy issues, or urgent messages that require immediate provider escalation."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["NDIS providers have conduct, quality, safeguarding, complaint, and incident responsibilities.","The VA should not investigate serious incidents independently.","Complaint handling should not discourage or pressure participants.","Urgency may depend on safety, harm, abuse, neglect, exploitation, privacy, or service disruption.","Records should be factual and access-controlled."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Preserve the participant or reporter''s words.","Record time, channel, people involved, and immediate known facts.","Use the provider''s urgent escalation contact.","Do not debate or promise an outcome.","Secure related records.","Create the complaint/incident task or record as directed.","Keep follow-up ownership visible."]},{"type":"callout","title":"Administrative boundary","text":"Do not decide whether an event is reportable, conduct a safeguarding investigation, determine liability, or coach someone to change their account. Follow the provider''s current incident/compliance process."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Trying to solve a safeguarding allegation in chat","Minimizing a complaint because the participant is upset","Editing wording to make the provider look better","Sharing incident details widely","Waiting for normal business hours when the escalation process says immediate"]},{"type":"scenario","title":"Practice scenario","text":"A participant messages the VA saying a worker behaved in a way that made them feel unsafe. Explain the immediate admin response and what you must not do."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Safety first.","Preserve exact facts.","Escalate immediately under policy.","Do not investigate or suppress."]}]'::jsonb,30,2,false,1,null,null,now(),now())
