insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='ndis-administration-fundamentals'),'QA and Simulation','Maintain current records and apply the full workflow.',5) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=5),'ndis-admin-qa-record-integrity-and-provider-handoffs','NDIS Admin QA, Record Integrity, and Provider Handoffs','NDIS administration is vulnerable to drift: outdated templates, missing records, old pricing, incorrect contacts, stale agreements, incomplete rosters, and unresolved claim exceptions. Regular QA makes these visible.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Build a provider admin QA routine","Date-stamp regulatory content","Prepare clear exception reports"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"NDIS administration is vulnerable to drift: outdated templates, missing records, old pricing, incorrect contacts, stale agreements, incomplete rosters, and unresolved claim exceptions. Regular QA makes these visible."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Current official guidance should outrank old training notes.","Service agreements and pricing references need version control.","Claims and support records should reconcile.","Registration/compliance dates need owners.","Sensitive participant records require controlled access."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Maintain a current-source register for NDIS/Commission references.","Review stale templates and pricing references.","Sample participant files for missing admin documents.","Review unresolved claim/rejection queues.","Review access permissions.","Track registration/audit/compliance deadlines assigned by the provider.","Prepare an exception report for responsible owners."]},{"type":"callout","title":"Administrative boundary","text":"QA identifies issues; it does not certify that the provider is compliant with the NDIS Act, Rules, Practice Standards, pricing arrangements, or registration requirements."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Calling an internal checklist a compliance audit","Keeping undated NDIS training notes","Assuming old pricing remains valid","Closing claim exceptions without evidence","Giving broad participant access to temporary staff"]},{"type":"scenario","title":"Practice scenario","text":"Your QA finds an old service-agreement template, several unresolved rejected claims, and a registration certificate that predates a recent SIL change. Explain how you report these without declaring non-compliance."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use current official sources.","Date-stamp content.","QA surfaces exceptions.","Compliance conclusions stay with responsible specialists."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='ndis-administration-fundamentals') and position=5),'ndis-administration-composite-work-simulation','NDIS Administration Composite Work Simulation','This simulation tests real administrative judgment across participant records, service agreements, rosters, billing, claims, complaints, and 2026 registration awareness.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Run a mixed NDIS provider admin queue","Prioritize safeguarding and claim integrity","Produce a compliance-aware handoff without giving compliance advice"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"This simulation tests real administrative judgment across participant records, service agreements, rosters, billing, claims, complaints, and 2026 registration awareness."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Participant privacy","Service agreements","Support records","Claims","Pricing exceptions","SIL registration awareness","Complaints and safeguarding"]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the fictional queue.","Escalate safety and incident-related items first.","Resolve routine participant-record and agreement admin.","Reconcile roster/support evidence.","Prepare invoice or claim exceptions.","Flag outdated regulatory/pricing references.","Produce a provider handoff with clear owners."]},{"type":"callout","title":"Administrative boundary","text":"The final simulation is administrative only. Do not make participant support decisions, claim unsupported services, interpret legislation, determine reportability, or certify provider compliance."},{"type":"callout","title":"Keep this current","text":"NDIS legislation, registration requirements, pricing, portals, support-item rules, and Commission guidance can change. Verify current official NDIS and NDIS Quality and Safeguards Commission guidance before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Prioritizing claims above participant safety","Changing evidence to fit billing","Using outdated NDIS rules","Overstating registration status","Giving participants funding advice"]},{"type":"scenario","title":"Practice scenario","text":"A fictional provider has a participant complaint about worker conduct, an unsigned agreement change, a roster/log mismatch, a rejected claim, a late cancellation billing question, and an SIL registration task referencing old guidance. Build the safe work queue and handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Safeguarding first.","Evidence before claims.","Use current official guidance.","Keep advice and compliance conclusions with authorized owners."]}]'::jsonb,30,2,false,1,null,null,now(),now())
