values ((select id from public.training_courses where slug='ndis-administration-fundamentals'),null,'NDIS Administration Final Work Simulation','Complete the NDIS provider administration simulation covering participant privacy, service agreements, support evidence, claims/payment pathways, pricing exceptions, complaints/safeguarding, and current 2026 registration awareness. This is not a compliance certification and the learner must not provide funding, legal, clinical, or support-planning advice.','practical',null,1,false,now(),now());
